import { encode } from "jpeg-js";
export function jpegSegment(marker: number, body: Buffer) {
  const header = Buffer.alloc(4);
  header[0] = 255;
  header[1] = marker;
  header.writeUInt16BE(body.length + 2, 2);
  return Buffer.concat([header, body]);
}
export function orientationSegment(orientation: number, little = true) {
  const tiff = Buffer.alloc(26);
  tiff.write(little ? "II" : "MM");
  const short = (offset: number, value: number) =>
      little
        ? tiff.writeUInt16LE(value, offset)
        : tiff.writeUInt16BE(value, offset),
    long = (offset: number, value: number) =>
      little
        ? tiff.writeUInt32LE(value, offset)
        : tiff.writeUInt32BE(value, offset);
  short(2, 42);
  long(4, 8);
  short(8, 1);
  short(10, 0x112);
  short(12, 3);
  long(14, 1);
  short(18, orientation);
  return jpegSegment(
    0xe1,
    Buffer.concat([
      Buffer.from("Exif\0\0"),
      tiff,
      Buffer.from("Synthetic private GPS / notes"),
    ]),
  );
}
export function jpegFixture(width = 320, height = 240, orientation = 1) {
  const raw = Buffer.alloc(width * height * 4);
  for (let y = 0; y < height; y++)
    for (let x = 0; x < width; x++) {
      const i = (y * width + x) * 4,
        wall = x < 8 || y < 8 || x >= width - 8 || y >= height - 8;
      raw[i] = wall ? 64 : x < width / 2 ? 222 : 184;
      raw[i + 1] = wall ? 95 : 218;
      raw[i + 2] = wall ? 77 : 190;
      raw[i + 3] = 255;
    }
  const encoded = Buffer.from(encode({ width, height, data: raw }, 90).data);
  return Buffer.concat([
    encoded.subarray(0, 2),
    orientationSegment(orientation),
    encoded.subarray(2),
  ]);
}

// Fixed synthetic 3 × 2 samples generated by Pillow; runtime tests require no image tools.
export const progressiveJpegFixture = () =>
  Buffer.from(
    "",
    "base64",
  );
export const grayscaleJpegFixture = () =>
  Buffer.from(
    "",
    "base64",
  );
